import { createCourseLessons, groupLessonsIntoModules } from './create-lessons.js';

export const javascriptModules = [
  { id: 'js-intro', title: '1. Introduction à JavaScript', lessons: [{ id: 'js-first-script', title: 'Ajouter son premier script', level: 'Débutant', introduction: 'JavaScript est un langage standardisé par ECMAScript. Le navigateur fournit en plus des API comme document et addEventListener pour interagir avec une page. Un fichier externe évite de mélanger structure et comportement.', syntax: '<script src="app.js" defer></script>\nconsole.log("Bonjour");', explanation: 'defer télécharge le fichier pendant l’analyse HTML puis l’exécute après la construction du document. console.log affiche une valeur dans la console des outils de développement.', lineByLine: 'Un script classique placé tard dans body s’exécute à cet endroit. defer convient aux scripts classiques externes ; type="module" active les modules et leur comportement différé par défaut.', commonMistakes: 'Un chemin src erroné, une casse différente dans le nom du fichier ou une erreur de syntaxe empêchent le comportement attendu. Les API Web ne sont pas toutes présentes dans Node.js.', goodPractice: 'Commence par un fichier externe, lis la première erreur de console et utilise des noms précis. Les commentaires expliquent le pourquoi, pas chaque ligne évidente.', callout: 'ECMAScript décrit le langage ; DOM, Fetch et localStorage sont fournis par l’environnement navigateur.', example: { id: 'js-first-script', files: { html: '<h1 id="message">Le script va démarrer</h1>', css: 'body { font: 1rem system-ui; padding: 1rem; }', javascript: 'console.log("Le script est chargé");\ndocument.querySelector("#message").textContent = "JavaScript fonctionne !";' }, expectedResult: 'Le texte du titre change et un message apparaît dans la console de l’iframe.' }, exercises: [
    { prompt: 'Sélectionne l’élément d’identifiant message avec querySelector.', requiredSnippets: ['document.querySelector("#message")'], hint: 'L’identifiant CSS est précédé de #.', explanation: 'document.querySelector("#message") renvoie le premier élément dont l’id est message.' },
    { prompt: 'Affiche « Prêt » dans la console.', requiredSnippets: ['console.log(', 'Prêt'], hint: 'La méthode console.log reçoit une valeur.', explanation: 'console.log("Prêt"); écrit le texte dans la console.' },
    { prompt: 'Charge app.js après analyse du document sans bloquer le parsing HTML.', requiredSnippets: ['<script', 'src="app.js"', 'defer'], hint: 'Ajoute l’attribut defer au script externe.', explanation: '<script src="app.js" defer></script> télécharge le script puis le lance après l’analyse HTML.' }
  ], syntax: 'document.querySelector("#message").textContent = "Bonjour";', lineByLine: 'document est une API du navigateur. querySelector trouve le premier élément correspondant au sélecteur. textContent remplace son texte sans interpréter du HTML.', commonMistakes: 'N’appelle pas une méthode sur null : vérifie que le sélecteur existe ou que le script s’exécute après la construction du document.', goodPractice: 'Utilise defer ou un module et ouvre la console pour observer les erreurs.', related: ['DOM', 'Modules ES'], keywords: ['script', 'defer', 'console', 'ECMAScript', 'browser API', 'syntax'] }] },
  { id: 'js-values', title: '2. Variables et types', lessons: [{ id: 'js-variables-types', title: 'Déclarer des variables et comprendre les types', level: 'Débutant', introduction: 'Une variable associe un nom à une valeur. const interdit de réaffecter la liaison ; let autorise une nouvelle valeur. Les valeurs primitives incluent string, number, boolean, undefined, null, bigint et symbol.', syntax: 'const prenom = "Aïcha";\nlet points = 0;\npoints += 1;\nconsole.log(typeof points);', explanation: 'typeof indique le type général. null représente une absence intentionnelle, bien que typeof null renvoie historiquement "object". undefined signale souvent une valeur non définie.', lineByLine: 'Les conversions explicites Number(), String() et Boolean() sont plus lisibles qu’une conversion implicite. Les chaînes non vides et les objets sont truthy ; 0, "", null, undefined, NaN et false sont falsy.', commonMistakes: 'const ne rend pas les propriétés d’un objet immuables ; elle empêche seulement la réaffectation de la variable. Comparer avec == peut convertir les types.', goodPractice: 'Préfère const par défaut, puis let si la valeur doit être réaffectée. Utilise === pour les comparaisons et vérifie les conversions numériques.', callout: 'Array est un objet, mais Array.isArray(value) permet de le détecter sans ambiguïté.', example: { id: 'js-values', files: { html: '<p id="output"></p>', css: 'body { font: 1rem system-ui; }', javascript: 'const prix = 2500;\nlet quantite = 2;\nquantite += 1;\nconst total = prix * quantite;\ndocument.querySelector("#output").textContent = `Total : ${total} F CFA`;\nconsole.log(typeof total);' }, expectedResult: 'Le navigateur affiche un total calculé et la console indique le type number.' }, exercises: [
    { prompt: 'Déclare une constante prenom contenant le texte « Awa ».', requiredSnippets: ['const prenom', '"Awa"'], hint: 'Une chaîne littérale est entourée de guillemets.', explanation: 'const prenom = "Awa"; crée une liaison constante vers cette chaîne.' },
    { prompt: 'Convertis la chaîne valeur en nombre avec Number().', requiredSnippets: ['Number(valeur)'], hint: 'Appelle le constructeur Number avec la valeur.', explanation: 'Number(valeur) demande explicitement une conversion numérique.' },
    { prompt: 'Vérifie strictement que score vaut le nombre 10.', requiredSnippets: ['score === 10'], hint: 'Utilise l’opérateur de comparaison stricte.', explanation: 'score === 10 compare valeur et type sans coercition.' }
  ], syntax: 'const taux = 0.2; let total = 10; total += 2;', lineByLine: 'taux ne sera pas réaffecté. total est réaffecté avec l’opérateur composé +=.', commonMistakes: 'Réutiliser const sans l’initialiser est invalide ; réaffecter une constante lève une erreur.', goodPractice: 'Nomme les valeurs selon leur rôle plutôt que leur type et garde une portée aussi courte que possible.', related: ['Opérateurs', 'Objets'], keywords: ['let', 'const', 'string', 'number', 'boolean', 'null', 'undefined', 'typeof', 'truthy', 'falsy'] }] },
  { id: 'js-operators', title: '3. Opérateurs', lessons: [{ id: 'js-operators-logic', title: 'Comparer et combiner des valeurs', level: 'Débutant', introduction: 'Les opérateurs calculent des valeurs, comparent des données et choisissent une valeur de repli. Les opérateurs logiques court-circuitent : la partie droite n’est évaluée que si nécessaire.', syntax: 'const estMajeur = age >= 18;\nconst etiquette = nom ?? "Visiteur";\nconst ville = profil?.adresse?.ville;\nconst message = actif ? "En ligne" : "Absent";', explanation: '+ additionne des nombres ou concatène des chaînes. === compare strictement. &&, || et ! combinent des booléens mais renvoient parfois une des valeurs opérandes. ?? utilise le secours seulement pour null ou undefined.', lineByLine: '?. arrête l’accès et renvoie undefined quand la valeur à gauche est nullish. Le ternaire choisit l’une de deux expressions. ++ et -- modifient une valeur numérique.', commonMistakes: '|| remplace aussi 0, false et chaîne vide ; ?? ne le fait pas. Mélanger ?? avec && ou || sans parenthèses est syntaxiquement interdit.', goodPractice: 'Choisis l’opérateur selon la signification des données et ajoute des parenthèses lorsque l’intention n’est pas évidente.', callout: 'L’optional chaining évite une erreur de lecture, mais ne remplace pas la validation des données.', example: { id: 'js-operators', files: { html: '<p id="output"></p>', css: '', javascript: 'const profil = { nom: "Mariam", adresse: { ville: "Ouagadougou" } };\nconst ville = profil?.adresse?.ville ?? "Ville inconnue";\nconst statut = profil.nom ? "Profil disponible" : "Profil absent";\ndocument.querySelector("#output").textContent = `${profil.nom} · ${ville} · ${statut}`;' }, expectedResult: 'La chaîne de résultat utilise optional chaining et une valeur de secours.' }, exercises: [
    { prompt: 'Fournis « Anonyme » seulement si nom vaut null ou undefined.', requiredSnippets: ['nom ?? "Anonyme"'], hint: 'Utilise le coalescent nullish.', explanation: 'nom ?? "Anonyme" ne remplace nom que s’il est nullish.' },
    { prompt: 'Lis la propriété ville sans erreur si profil ou adresse est absent.', requiredSnippets: ['profil?.adresse?.ville'], hint: 'Place un ?. à chaque accès potentiellement absent.', explanation: 'profil?.adresse?.ville renvoie undefined si un maillon est null ou undefined.' },
    { prompt: 'Crée un message qui dépend de la valeur de connecte avec l’opérateur ternaire.', requiredSnippets: ['connecte ?', '"Connecté"', ':', '"Hors ligne"'], hint: 'La forme est condition ? valeurSiVrai : valeurSinon.', explanation: 'connecte ? "Connecté" : "Hors ligne" choisit l’un des deux textes.' }
  ], syntax: 'const affichage = prenom ?? "Visiteur";', lineByLine: 'Si prenom est null ou undefined, l’expression renvoie Visiteur. Une chaîne vide reste une chaîne vide.', commonMistakes: 'Ne mélange pas ?? avec || sans parenthèses. Ne suppose pas qu’un résultat falsy équivaut à une valeur absente.', goodPractice: 'Utilise des comparaisons strictes et évite les expressions imbriquées trop complexes.', related: ['Conditions et boucles', 'Valeurs primitives'], keywords: ['operators', 'ternary', 'nullish', 'optional chaining', 'arithmetic', 'comparison', 'logical'] }] },
  { id: 'js-control-flow', title: '4. Conditions et boucles', lessons: [{ id: 'js-loops-conditions', title: 'Choisir une action et répéter du code', level: 'Débutant', introduction: 'Les conditions exécutent un bloc selon un test. Les boucles répètent un bloc tant qu’une condition ou une collection le demande.', syntax: 'if (score >= 10) { ... } else { ... }\nfor (const fruit of fruits) { ... }\nfor (const cle in objet) { ... }', explanation: 'if/else convient à des branches booléennes ; switch compare une expression à plusieurs cas. for est utile avec un compteur, while répète selon une condition et for...of parcourt les valeurs itérables.', lineByLine: 'for...in énumère les clés propres énumérables, notamment celles d’un objet ; il n’est généralement pas le bon outil pour parcourir les valeurs d’un tableau. break arrête une boucle et continue passe à l’itération suivante.', commonMistakes: 'Une boucle while sans progression peut tourner indéfiniment. Oublier break dans un switch peut enchaîner les cas suivants.', goodPractice: 'Choisis la boucle la plus lisible et vérifie que chaque boucle possède une condition de sortie atteignable.', callout: 'for...of parcourt les valeurs ; for...in parcourt les noms de propriétés.', example: { id: 'js-control-flow', files: { html: '<ul id="output"></ul>', css: 'li { margin: .4rem 0; font: 1rem system-ui; }', javascript: 'const temperatures = [28, 31, 26];\nconst liste = document.querySelector("#output");\nfor (const temperature of temperatures) {\n  const item = document.createElement("li");\n  item.textContent = temperature >= 30 ? `${temperature}° : chaud` : `${temperature}° : doux`;\n  liste.append(item);\n}' }, expectedResult: 'La boucle construit un élément de liste pour chaque température.' }, exercises: [
    { prompt: 'Écris une condition qui teste si score est supérieur ou égal à 10.', requiredSnippets: ['if (score >= 10)'], hint: 'Utilise le mot-clé if et une comparaison.', explanation: 'if (score >= 10) { ... } exécute le bloc si le test est vrai.' },
    { prompt: 'Parcours les valeurs de fruits avec for...of.', requiredSnippets: ['for (const fruit of fruits)'], hint: 'La forme inclut une variable, of et l’itérable.', explanation: 'for (const fruit of fruits) { ... } reçoit chaque valeur du tableau.' },
    { prompt: 'Écris une boucle while qui avance index jusqu’à la longueur du tableau.', requiredSnippets: ['while (index < items.length)', 'index++'], hint: 'La variable de boucle doit progresser dans le corps.', explanation: 'while (index < items.length) { ...; index++; } termine quand chaque index a été parcouru.' }
  ], syntax: 'for (const valeur of collection) { ... }', lineByLine: 'À chaque tour, valeur reçoit le prochain élément. La boucle se termine une fois la collection épuisée.', commonMistakes: 'Modifier le tableau que l’on parcourt peut rendre le résultat surprenant ; choisis une copie si tu dois changer sa structure.', goodPractice: 'for...of est souvent le parcours le plus direct quand l’index n’est pas nécessaire.', related: ['Tableaux', 'Fonctions'], keywords: ['if', 'else', 'switch', 'for', 'while', 'do while', 'for of', 'for in', 'break', 'continue'] }] },
  { id: 'js-functions', title: '5. Fonctions', lessons: [{ id: 'js-function-scope', title: 'Créer des fonctions réutilisables', level: 'Débutant', introduction: 'Une fonction regroupe une responsabilité. Elle peut recevoir des paramètres et renvoyer une valeur. Les fonctions fléchées donnent une syntaxe concise, notamment pour les callbacks.', syntax: 'function total(prix, quantite = 1) { return prix * quantite; }\nconst doubler = valeur => valeur * 2;', explanation: 'Les déclarations de fonction sont disponibles avant leur position dans le bloc grâce au hoisting. let et const ne sont pas utilisables avant leur initialisation. Une closure conserve l’accès aux variables de sa portée lexicale.', lineByLine: 'return termine l’appel et fournit son résultat. Une fonction sans return explicite renvoie undefined. Une fonction de rappel est transmise à une autre fonction pour être appelée plus tard.', commonMistakes: 'Confondre afficher une valeur et la retourner empêche sa réutilisation. Une fonction fléchée ne possède pas son propre this.', goodPractice: 'Donne un nom au comportement, garde les fonctions petites et retourne plutôt que modifier des variables globales.', callout: 'Le hoisting ne signifie pas que toutes les déclarations remontent de la même façon.', example: { id: 'js-functions', files: { html: '<p id="output"></p>', css: '', javascript: 'function calculerSousTotal(prix, quantite = 1) {\n  return prix * quantite;\n}\nconst prix = 1500;\nconst sousTotal = calculerSousTotal(prix, 3);\ndocument.querySelector("#output").textContent = `${sousTotal} F CFA`;\nconsole.log(calculerSousTotal(2000));' }, expectedResult: 'La fonction renvoie le sous-total de trois articles et utilise 1 par défaut si la quantité manque.' }, exercises: [
    { prompt: 'Déclare une fonction ajouter qui reçoit a et b et renvoie leur somme.', requiredSnippets: ['function ajouter(a, b)', 'return a + b'], hint: 'Place le calcul dans une instruction return.', explanation: 'function ajouter(a, b) { return a + b; } renvoie la somme.' },
    { prompt: 'Donne la valeur par défaut 1 au paramètre quantite.', requiredSnippets: ['quantite = 1'], hint: 'La valeur par défaut s’écrit dans la liste des paramètres.', explanation: 'function total(prix, quantite = 1) fournit une unité par défaut.' },
    { prompt: 'Écris une fonction fléchée doubler qui renvoie n multiplié par 2.', requiredSnippets: ['const doubler', '=>', 'n * 2'], hint: 'Une fonction fléchée utilise =>.', explanation: 'const doubler = n => n * 2; renvoie implicitement le produit.' }
  ], syntax: 'const saluer = (nom = "ami") => `Bonjour ${nom}`;', lineByLine: 'La valeur par défaut est utilisée quand aucun argument n’est transmis ou quand l’argument vaut undefined. Le template literal insère nom dans le texte.', commonMistakes: 'Une chaîne vide n’active pas la valeur par défaut ; seule une omission ou undefined le fait.', goodPractice: 'Précise les entrées, produis un résultat explicite et évite d’utiliser les paramètres pour des effets cachés.', related: ['Callbacks', 'Closures'], keywords: ['function', 'arrow', 'arguments', 'parameters', 'return', 'scope', 'hoisting', 'closure', 'callback'] }] },
  { id: 'js-strings', title: '6. Chaînes de caractères', lessons: [{ id: 'js-string-methods', title: 'Transformer et chercher dans un texte', level: 'Débutant', introduction: 'Les chaînes JavaScript sont immuables : leurs méthodes produisent une nouvelle chaîne au lieu de modifier l’originale. Les template literals simplifient l’interpolation et les chaînes multilignes.', syntax: 'const propre = texte.trim();\nconst morceaux = propre.split(",");\nconst trouve = propre.includes("web");\nconst url = `https://exemple.test?q=${encodeURIComponent(propre)}`;', explanation: 'length donne le nombre d’unités de code UTF-16, qui peut différer du nombre de graphèmes visibles. slice extrait une partie ; substring a des règles légèrement différentes pour les indices négatifs.', lineByLine: 'includes, startsWith et endsWith renvoient des booléens. replace remplace une première occurrence ou celles reconnues par une expression régulière globale. split transforme la chaîne en tableau.', commonMistakes: 'Les chaînes ne se modifient pas en place. Pour remplacer toutes les occurrences, configure le motif approprié ou utilise replaceAll.', goodPractice: 'Nettoie les valeurs utilisateur selon le besoin, mais ne confonds pas nettoyage de texte et validation métier.', callout: 'Pour construire une URL, URL et URLSearchParams évitent de concaténer manuellement des paramètres.', example: { id: 'js-strings', files: { html: '<p id="output"></p>', css: '', javascript: 'const tags = " HTML, CSS, JavaScript ";\nconst technologies = tags.trim().split(", ");\nconst phrase = technologies.map((name) => name.toUpperCase()).join(" · ");\ndocument.querySelector("#output").textContent = phrase;\nconsole.log(tags.includes("CSS"));' }, expectedResult: 'Les espaces sont retirés, les technologies sont séparées puis affichées en majuscules.' }, exercises: [
    { prompt: 'Retire les espaces au début et à la fin de texte.', requiredSnippets: ['texte.trim()'], hint: 'La méthode s’appelle trim.', explanation: 'texte.trim() renvoie une chaîne sans espaces périphériques.' },
    { prompt: 'Sépare csv en éléments avec une virgule comme séparateur.', requiredSnippets: ['csv.split(",")'], hint: 'split reçoit le séparateur.', explanation: 'csv.split(",") produit un tableau de morceaux.' },
    { prompt: 'Construis un template literal qui inclut la variable nom.', requiredSnippets: ['`', '${nom}'], hint: 'L’interpolation utilise ${...} entre accents graves.', explanation: '`Bonjour ${nom}` insère la valeur de nom dans une nouvelle chaîne.' }
  ], syntax: 'const phrase = `Bonjour ${prenom.trim()}`;', lineByLine: 'Les accents graves créent le template literal. ${...} évalue une expression JavaScript puis insère sa représentation dans la chaîne.', commonMistakes: 'Les guillemets simples ou doubles ne permettent pas cette interpolation.', goodPractice: 'Utilise des template literals pour composer des chaînes lisibles et évite les concaténations longues.', related: ['Tableaux', 'Expressions régulières'], keywords: ['length', 'charAt', 'includes', 'slice', 'substring', 'trim', 'replace', 'split', 'startsWith', 'endsWith', 'template literal'] }] },
  { id: 'js-arrays', title: '7. Tableaux', lessons: [{ id: 'js-array-methods', title: 'Parcourir et transformer des tableaux', level: 'Intermédiaire', introduction: 'Un tableau ordonné contient des valeurs accessibles par index à partir de zéro. Certaines méthodes modifient le tableau ; d’autres produisent un résultat dérivé.', syntax: 'const noms = ["Awa", "Issa"];\nnoms.push("Mariam");\nconst majuscules = noms.map(nom => nom.toUpperCase());\nconst longs = noms.filter(nom => nom.length > 3);', explanation: 'push/pop ajoutent ou retirent à la fin ; shift/unshift agissent au début. slice copie une portion sans modifier l’original ; splice insère ou retire en place.', lineByLine: 'map transforme chaque élément. filter sélectionne ceux qui satisfont un test. find renvoie le premier correspondant ; findIndex son index. reduce accumule une valeur. some et every testent les éléments.', commonMistakes: 'sort() convertit par défaut en chaînes et trie lexicalement ; pour des nombres utilise (a, b) => a - b. Ne réutilise pas le même nom de variable pour le tableau et ses éléments.', goodPractice: 'Préfère map/filter pour produire un nouveau tableau et réserve splice aux mutations intentionnelles. La syntaxe spread copie superficiellement.', callout: 'Les tableaux multidimensionnels sont des tableaux contenant d’autres tableaux ; valide chaque niveau avant d’accéder à un index.', example: { id: 'js-arrays', files: { html: '<ul id="output"></ul>', css: 'li { font: 1rem system-ui; margin: .3rem; }', javascript: 'const prix = [1200, 800, 2500, 900];\nconst abordables = prix.filter((montant) => montant < 1500);\nconst liste = document.querySelector("#output");\nfor (const montant of abordables) {\n  const item = document.createElement("li");\n  item.textContent = `${montant} F CFA`;\n  liste.append(item);\n}' }, expectedResult: 'Seuls les montants inférieurs à 1500 sont affichés.' }, exercises: [
    { prompt: 'Ajoute « orange » à la fin du tableau fruits.', requiredSnippets: ['fruits.push("orange")'], hint: 'push ajoute un élément à la fin.', explanation: 'fruits.push("orange") ajoute cette valeur au tableau.' },
    { prompt: 'Crée un tableau double contenant chaque nombre multiplié par deux avec map.', requiredSnippets: ['nombres.map(', '=>', '* 2'], hint: 'map reçoit une fonction de transformation.', explanation: 'const double = nombres.map(n => n * 2); transforme chaque valeur.' },
    { prompt: 'Trie les nombres par ordre numérique croissant avec un comparateur.', requiredSnippets: ['.sort(', 'a - b'], hint: 'Le comparateur renvoie une différence numérique.', explanation: 'nombres.sort((a, b) => a - b) trie numériquement en place.' }
  ], syntax: 'const total = prix.reduce((somme, prixUnitaire) => somme + prixUnitaire, 0);', lineByLine: 'somme est l’accumulateur initialisé à zéro. À chaque élément, le callback renvoie la nouvelle somme. Le résultat final est un seul nombre.', commonMistakes: 'Sans valeur initiale, reduce peut échouer sur un tableau vide et traiter le premier élément comme accumulateur.', goodPractice: 'Fournis une valeur initiale à reduce et choisis map, filter ou find lorsqu’ils expriment plus directement l’objectif.', related: ['Fonctions de rappel', 'Objets'], keywords: ['push', 'pop', 'shift', 'unshift', 'slice', 'splice', 'find', 'filter', 'map', 'reduce', 'some', 'every', 'sort', 'spread'] }] },
  { id: 'js-objects', title: '8. Objets', lessons: [{ id: 'js-object-properties', title: 'Regrouper des données dans un objet', level: 'Intermédiaire', introduction: 'Un objet associe des clés à des valeurs et représente souvent une entité métier. Ses propriétés peuvent contenir des primitives, d’autres objets ou des fonctions appelées méthodes.', syntax: 'const personne = { nom: "Awa", ville: "Bobo", saluer() { return `Salut ${this.nom}`; } };\nconst { nom, ...reste } = personne;\nconst copie = { ...personne, ville: "Ouaga" };', explanation: 'Object.keys, Object.values et Object.entries parcourent les propriétés propres énumérables. this dépend de la façon dont une méthode est appelée ; une fonction fléchée n’a pas son propre this.', lineByLine: 'La destructuration extrait des propriétés. spread copie les propriétés propres énumérables dans un nouvel objet. Cette copie est superficielle : les objets imbriqués restent partagés.', commonMistakes: 'Réaffecter une propriété d’un objet const est permis, mais remplacer l’objet ne l’est pas. Une copie superficielle ne protège pas les objets imbriqués contre les mutations.', goodPractice: 'Utilise des objets simples et des noms de propriétés stables. Pour des données imbriquées, décide explicitement si tu dois copier les niveaux concernés.', callout: 'Map est mieux adapté aux collections de clés dynamiques ; un objet convient aux enregistrements structurés.', example: { id: 'js-objects', files: { html: '<p id="output"></p>', css: '', javascript: 'const produit = { nom: "Panier de mangues", prix: 3500, stock: 4 };\nconst { nom, prix } = produit;\nconst copie = { ...produit, stock: produit.stock - 1 };\ndocument.querySelector("#output").textContent = `${nom} : ${prix} F CFA, stock ${copie.stock}`;\nconsole.log(Object.keys(produit));' }, expectedResult: 'Une copie du produit affiche un stock décrémenté sans modifier l’objet initial.' }, exercises: [
    { prompt: 'Crée un objet profil avec la propriété nom égale à « Issa ».', requiredSnippets: ['const profil', 'nom:', '"Issa"'], hint: 'Un objet utilise des accolades et des propriétés clé-valeur.', explanation: 'const profil = { nom: "Issa" }; crée un objet avec une propriété nom.' },
    { prompt: 'Récupère nom depuis personne avec la destructuration.', requiredSnippets: ['const { nom } = personne'], hint: 'La syntaxe destructurée utilise des accolades à gauche.', explanation: 'const { nom } = personne; lit la propriété nom.' },
    { prompt: 'Crée un nouvel objet qui copie produit et remplace son stock par zéro.', requiredSnippets: ['...produit', 'stock:', '0'], hint: 'Spread copie les propriétés avant la surcharge explicite.', explanation: 'const vide = { ...produit, stock: 0 }; crée une copie superficielle avec un stock nul.' }
  ], syntax: 'const copie = { ...source, actif: true };', lineByLine: 'Les propriétés de source sont copiées, puis actif est défini. En cas de clé répétée, la dernière valeur gagne.', commonMistakes: 'Un spread placé après actif écraserait la valeur choisie si source possède aussi une propriété actif.', goodPractice: 'Soigne l’ordre des propriétés et traite les mutations des objets partagés comme des effets visibles.', related: ['Tableaux', 'Classes'], keywords: ['Object.keys', 'Object.values', 'Object.entries', 'this', 'destructuring', 'spread', 'rest', 'shallow copy', 'references'] }] },
  { id: 'js-builtins', title: '9. Nombres, dates et objets natifs', lessons: [{ id: 'js-builtins-json-intl', title: 'Calculer, formater et échanger des données', level: 'Intermédiaire', introduction: 'Le langage fournit des objets natifs pour les nombres, les dates et les collections. JSON est un format texte d’échange ; Intl adapte le formatage à une langue et à une région.', syntax: 'const arrondi = Math.round(4.6);\nconst montant = new Intl.NumberFormat("fr-FR").format(12500);\nconst donnees = JSON.parse("{\\"ok\\":true}");\nconst uniques = new Set([1, 1, 2]);', explanation: 'Math.floor arrondit vers le bas, round au plus proche et random produit une valeur pseudo-aléatoire dans [0,1). Date représente un instant en millisecondes. Map et Set gèrent des collections spécialisées.', lineByLine: 'JSON.stringify sérialise les données compatibles ; JSON.parse les reconstruit et peut lancer une erreur sur un texte invalide. Les expressions régulières reconnaissent des motifs, mais ne remplacent pas toutes les règles métier.', commonMistakes: 'Les dates stockées en heure locale peuvent varier selon fuseau ; un Set ne déduplique pas deux objets distincts de même contenu. JSON ne représente ni fonctions ni références cycliques.', goodPractice: 'Garde un instant interne explicite et formate-le avec Intl à l’affichage. Valide les entrées avant de les parser ou de les utiliser.', callout: 'Les valeurs issues du stockage ou du réseau restent non fiables, même après un JSON.parse réussi.', example: { id: 'js-builtins', files: { html: '<p id="output"></p>', css: '', javascript: 'const ventes = [1200, 1800, 1500];\nconst total = ventes.reduce((s, valeur) => s + valeur, 0);\nconst prixFormate = new Intl.NumberFormat("fr-FR", { style: "currency", currency: "XOF" }).format(total);\nconst uniques = [...new Set(ventes)];\ndocument.querySelector("#output").textContent = `${prixFormate} · ${uniques.length} ventes`;\nconsole.log(new Date().toISOString());' }, expectedResult: 'Le total est formaté selon la locale et la console affiche une date ISO.' }, exercises: [
    { prompt: 'Arrondis vers le bas la valeur prix avec Math.floor.', requiredSnippets: ['Math.floor(prix)'], hint: 'La méthode est dans l’objet Math.', explanation: 'Math.floor(prix) renvoie l’entier inférieur ou égal à prix.' },
    { prompt: 'Formate un nombre avec la locale française via Intl.NumberFormat.', requiredSnippets: ['Intl.NumberFormat("fr-FR")'], hint: 'Le constructeur accepte la locale en premier argument.', explanation: 'new Intl.NumberFormat("fr-FR").format(valeur) produit un format français.' },
    { prompt: 'Élimine les doublons du tableau valeurs avec Set.', requiredSnippets: ['[...new Set(valeurs)]'], hint: 'Set stocke les valeurs uniques ; spread reconstruit un tableau.', explanation: '[...new Set(valeurs)] produit un tableau des valeurs uniques.' }
  ], syntax: 'const uniques = [...new Set(valeurs)];', lineByLine: 'Set ne conserve qu’une occurrence de chaque valeur primitive. Spread place ensuite les valeurs dans un nouveau tableau.', commonMistakes: 'Les objets sont comparés par identité, donc deux objets distincts avec les mêmes propriétés restent deux valeurs différentes.', goodPractice: 'Pour des devises, stocke des unités entières si la précision décimale est critique et formate seulement à l’affichage.', related: ['Tableaux', 'Asynchronisme'], keywords: ['Math', 'Number', 'Date', 'Intl', 'Set', 'Map', 'JSON', 'RegExp'] }] },
  { id: 'js-oop', title: '10. Programmation orientée objet', lessons: [{ id: 'js-classes-prototypes', title: 'Classes, prototypes et héritage', level: 'Avancé', introduction: 'JavaScript repose sur des prototypes. La syntaxe class offre une manière familière de définir des constructeurs, méthodes, accesseurs et relations d’héritage sans remplacer le modèle prototype.', syntax: 'class Produit {\n  constructor(nom) { this.nom = nom; }\n  get etiquette() { return `Produit : ${this.nom}`; }\n  static creerAnonyme() { return new Produit("Sans nom"); }\n}', explanation: 'extends établit l’héritage et super() appelle le constructeur parent. Les champs privés # ne sont accessibles qu’à l’intérieur de la classe. Les méthodes sont partagées via le prototype.', lineByLine: 'Un getter est lu comme une propriété. static appartient à la classe elle-même. Les objets gardent leurs propriétés propres tandis que les méthodes de classe sont généralement sur le prototype.', commonMistakes: 'Appeler une méthode détachée peut perdre son this. Un getter ne doit pas lancer de calcul coûteux à chaque lecture.', goodPractice: 'Utilise une classe lorsqu’elle clarifie un modèle avec état et comportement ; un objet simple suffit souvent pour de simples données.', callout: 'Les classes JS ne sont pas identiques aux classes d’autres langages ; elles construisent des objets selon le système prototype.', example: { id: 'js-classes', files: { html: '<p id="output"></p>', css: '', javascript: 'class Compteur {\n  #valeur = 0;\n  augmenter() { this.#valeur += 1; return this.#valeur; }\n  get valeur() { return this.#valeur; }\n}\nconst compteur = new Compteur();\ncompteur.augmenter();\ndocument.querySelector("#output").textContent = `Valeur : ${compteur.valeur}`;' }, expectedResult: 'Le compteur possède un état privé exposé par un getter.' }, exercises: [
    { prompt: 'Déclare une classe Produit avec un constructeur.', requiredSnippets: ['class Produit', 'constructor('], hint: 'Le mot-clé class précède le nom.', explanation: 'class Produit { constructor(...) { ... } } déclare une classe et son initialiseur.' },
    { prompt: 'Déclare une classe Animal qui hérite de Creature.', requiredSnippets: ['class Animal extends Creature'], hint: 'Le mot-clé extends établit l’héritage.', explanation: 'class Animal extends Creature indique que Animal étend Creature.' },
    { prompt: 'Ajoute un champ privé #stock initialisé à zéro.', requiredSnippets: ['#stock = 0'], hint: 'Les champs privés commencent par #.', explanation: '#stock = 0; déclare un champ privé accessible dans le corps de classe.' }
  ], syntax: 'class Enfant extends Parent { constructor() { super(); } }', lineByLine: 'extends établit la chaîne de prototypes. super appelle le constructeur parent avant d’accéder à this.', commonMistakes: 'Dans un constructeur dérivé, super() doit précéder l’utilisation de this.', goodPractice: 'Évite l’héritage profond et préfère la composition quand plusieurs comportements doivent être combinés.', related: ['Objets', 'this et fonctions'], keywords: ['class', 'constructor', 'getters', 'setters', 'extends', 'super', 'prototype', 'static', 'private fields'] }] },
  { id: 'js-dom', title: '11. DOM', lessons: [{ id: 'js-dom-manipulation', title: 'Sélectionner et modifier la page', level: 'Intermédiaire', introduction: 'Le DOM est l’interface navigateur qui représente le document comme des nœuds. JavaScript peut sélectionner des éléments, modifier leur texte, leurs attributs et classes, ou créer puis insérer de nouveaux nœuds.', syntax: 'const liste = document.querySelector("#liste");\nconst item = document.createElement("li");\nitem.textContent = "Mangue";\nliste.append(item);', explanation: 'querySelector renvoie le premier résultat ou null ; querySelectorAll renvoie une NodeList statique. textContent insère du texte brut. innerHTML analyse une chaîne comme HTML et peut créer une faille si elle contient des données non fiables.', lineByLine: 'classList.add/remove/toggle gère les classes. setAttribute modifie un attribut ; remove retire un nœud. parentElement, children et closest aident à parcourir la structure.', commonMistakes: 'Écrire une chaîne utilisateur dans innerHTML expose au XSS. Modifier la collection pendant qu’on la parcourt peut sauter des éléments.', goodPractice: 'Préfère textContent, createElement et les méthodes DOM. Vérifie les sélecteurs qui peuvent ne rien trouver.', callout: 'Le DOM est une API Web du navigateur, pas une partie du cœur ECMAScript.', example: { id: 'js-dom', files: { html: '<ul id="liste"></ul>', css: 'li { padding: .4rem; font: 1rem system-ui; }', javascript: 'const activites = ["Lire", "Dessiner", "Coder"];\nconst liste = document.querySelector("#liste");\nfor (const activite of activites) {\n  const item = document.createElement("li");\n  item.textContent = activite;\n  liste.append(item);\n}\nliste.classList.add("ready");' }, expectedResult: 'Une liste est construite à partir du tableau, sans insérer de HTML non fiable.' }, exercises: [
    { prompt: 'Sélectionne le premier élément d’id liste.', requiredSnippets: ['document.querySelector("#liste")'], hint: 'Utilise un sélecteur CSS d’identifiant.', explanation: 'document.querySelector("#liste") sélectionne l’élément voulu.' },
    { prompt: 'Crée un élément li avec createElement.', requiredSnippets: ['document.createElement("li")'], hint: 'La méthode appartient à document.', explanation: 'document.createElement("li") crée un élément qui n’est pas encore inséré.' },
    { prompt: 'Ajoute item à la fin de liste sans réinterpréter son texte.', requiredSnippets: ['item.textContent', 'liste.append(item)'], hint: 'Utilise textContent puis append.', explanation: 'item.textContent = valeur; liste.append(item); insère le nœud avec du texte sûr.' }
  ], syntax: 'element.classList.toggle("actif");', lineByLine: 'classList est une API DOM spécialisée dans la liste de classes. toggle ajoute la classe si elle manque et la retire si elle existe.', commonMistakes: 'L’assignation directe à className remplace toutes les classes existantes.', goodPractice: 'Garde la logique de présentation dans CSS et demande au DOM de changer des classes significatives.', related: ['Événements', 'Sécurité des entrées'], keywords: ['DOM', 'querySelector', 'querySelectorAll', 'textContent', 'innerHTML', 'attributes', 'classList', 'createElement', 'append', 'remove'] }] },
  { id: 'js-events', title: '12. Événements', lessons: [{ id: 'js-events-delegation', title: 'Réagir aux événements', level: 'Intermédiaire', introduction: 'Un gestionnaire d’événement relie une action du navigateur à une fonction. L’objet événement décrit la source et les propriétés de l’action.', syntax: 'bouton.addEventListener("click", (event) => {\n  event.currentTarget.classList.toggle("actif");\n});', explanation: 'target est l’élément d’origine ; currentTarget est l’élément qui porte le gestionnaire. preventDefault annule l’action native. Les événements remontent souvent dans le DOM via la propagation.', lineByLine: 'La délégation place un gestionnaire sur un parent et reconnaît les descendants concernés avec closest(). Elle évite d’attacher un gestionnaire à chaque ligne générée.', commonMistakes: 'Utiliser une fonction fléchée et attendre un this différent de la portée extérieure mène à un comportement inattendu. stopPropagation devrait être rare.', goodPractice: 'Utilise addEventListener, sépare les gestionnaires nommés lorsqu’il faut les retirer et vérifie les cibles déléguées.', callout: 'submit se produit aussi quand la personne appuie sur Entrée dans un formulaire ; écoute le formulaire plutôt que seulement le bouton.', example: { id: 'js-events', files: { html: '<ul id="tasks"><li><button data-task="1">Terminer la tâche 1</button></li><li><button data-task="2">Terminer la tâche 2</button></li></ul><p id="feedback"></p>', css: 'button.done { background: #176b45; color: white; }', javascript: 'const tasks = document.querySelector("#tasks");\ntasks.addEventListener("click", (event) => {\n  const button = event.target.closest("button[data-task]");\n  if (!button) return;\n  button.classList.toggle("done");\n  document.querySelector("#feedback").textContent = `Tâche ${button.dataset.task} mise à jour`;\n});' }, expectedResult: 'Un seul écouteur parent gère les boutons présents et ceux ajoutés plus tard.' }, exercises: [
    { prompt: 'Ajoute un écouteur click à bouton.', requiredSnippets: ['bouton.addEventListener("click"'], hint: 'La méthode reçoit le nom d’événement et un callback.', explanation: 'bouton.addEventListener("click", callback) écoute les clics.' },
    { prompt: 'Empêche la soumission native du formulaire avec l’événement event.', requiredSnippets: ['event.preventDefault()'], hint: 'L’objet événement fournit cette méthode.', explanation: 'event.preventDefault() annule l’action native associée.' },
    { prompt: 'Dans une délégation, trouve le bouton ancêtre le plus proche depuis event.target.', requiredSnippets: ['event.target.closest("button")'], hint: 'closest remonte les ancêtres jusqu’au sélecteur.', explanation: 'event.target.closest("button") trouve le bouton déclencheur ou son ancêtre bouton.' }
  ], syntax: 'parent.addEventListener("click", gererClic);', lineByLine: 'Le parent reçoit les clics propagés depuis ses descendants. Le callback vérifie ensuite si la cible correspond à une action connue.', commonMistakes: 'Un clic sur une icône interne rend event.target différent du bouton ; closest couvre ce cas.', goodPractice: 'Filtre toujours les événements délégués et garde un nom accessible aux actions.', related: ['DOM', 'Formulaires'], keywords: ['addEventListener', 'event', 'target', 'currentTarget', 'preventDefault', 'propagation', 'delegation', 'keyboard'] }] },
  { id: 'js-forms', title: '13. Formulaires et validation', lessons: [{ id: 'js-form-validation', title: 'Lire et valider un formulaire', level: 'Intermédiaire', introduction: 'Les formulaires HTML offrent déjà des contraintes comme required, type=email et minlength. JavaScript peut compléter ces règles et présenter un retour compréhensible sans supprimer la validation native.', syntax: 'form.addEventListener("submit", (event) => {\n  event.preventDefault();\n  const donnees = new FormData(form);\n});', explanation: 'FormData lit les champs possédant un name. checkValidity() vérifie les contraintes natives ; setCustomValidity() ajoute un message personnalisé, à réinitialiser lorsque la valeur change.', lineByLine: 'Un message d’erreur doit identifier le champ, expliquer comment corriger la valeur et être associé au contrôle via aria-describedby. Une validation serveur reste nécessaire pour des données envoyées.', commonMistakes: 'Se fier seulement à JavaScript permet de contourner la validation. Une erreur uniquement colorée ou annoncée visuellement peut ne pas être perçue.', goodPractice: 'Commence par les attributs HTML, ajoute un message textuel, garde le focus cohérent et teste la soumission au clavier.', callout: 'Les champs de mot de passe et les données personnelles nécessitent une gestion prudente ; ne les stocke pas dans localStorage par défaut.', example: { id: 'js-forms', files: { html: '<form id="signup"><label for="email">Adresse e-mail</label><input id="email" name="email" type="email" required><button>Vérifier</button></form><p id="feedback" role="status"></p>', css: 'form { display: flex; gap: .5rem; font: 1rem system-ui; }', javascript: 'const form = document.querySelector("#signup");\nform.addEventListener("submit", (event) => {\n  event.preventDefault();\n  const data = new FormData(form);\n  const email = data.get("email");\n  document.querySelector("#feedback").textContent = `Adresse valide : ${email}`;\n});' }, expectedResult: 'Le navigateur bloque les formats email invalides puis JavaScript affiche la valeur après validation.' }, exercises: [
    { prompt: 'Écoute la soumission du formulaire form.', requiredSnippets: ['form.addEventListener("submit"'], hint: 'L’événement se nomme submit.', explanation: 'form.addEventListener("submit", callback) gère la validation au moment de l’envoi.' },
    { prompt: 'Lis le champ email avec FormData.', requiredSnippets: ['new FormData(form)', 'data.get("email")'], hint: 'FormData prend le formulaire et fournit get.', explanation: 'const data = new FormData(form); data.get("email"); lit le champ nommé email.' },
    { prompt: 'Vérifie les contraintes natives du formulaire avant de continuer.', requiredSnippets: ['form.checkValidity()'], hint: 'Le formulaire possède une méthode de validation.', explanation: 'form.checkValidity() renvoie un booléen selon les contraintes natives.' }
  ], syntax: 'const donnees = new FormData(form);', lineByLine: 'FormData collecte les champs nommés activés. get renvoie la valeur associée au nom demandé.', commonMistakes: 'Un contrôle sans attribut name ne sera pas présent dans FormData.', goodPractice: 'Associe label à chaque champ et conserve les validations HTML natives.', related: ['Événements', 'Expressions régulières'], keywords: ['FormData', 'validity', 'required', 'email', 'pattern', 'aria-describedby'] }] },
  { id: 'js-async', title: '14. Programmation asynchrone', lessons: [{ id: 'js-promises-async', title: 'Comprendre les promesses et async/await', level: 'Intermédiaire', introduction: 'Une opération asynchrone termine plus tard et laisse la page répondre. Une Promise représente une valeur future qui peut être accomplie ou rejetée.', syntax: 'async function charger() {\n  try {\n    const valeur = await promesse;\n    return valeur;\n  } catch (erreur) {\n    console.error(erreur);\n  }\n}', explanation: 'then traite la réussite, catch le rejet et finally s’exécute dans les deux cas. Une fonction async renvoie toujours une Promise. await suspend cette fonction jusqu’à la résolution.', lineByLine: 'Promise.all attend plusieurs promesses et échoue dès qu’une est rejetée. setTimeout planifie une fonction plus tard ; setInterval la répète jusqu’à clearInterval.', commonMistakes: 'Oublier await peut afficher une Promise au lieu de sa valeur. Une exception dans un callback asynchrone doit être traitée dans la chaîne correspondante.', goodPractice: 'Encapsule les opérations asynchrones dans des fonctions async lisibles et prévois un chemin d’erreur explicite.', callout: 'JavaScript exécute le code synchrone sur un thread principal, tandis que la boucle d’événements orchestre les tâches et callbacks.', example: { id: 'js-async', files: { html: '<p id="output">En attente…</p>', css: '', javascript: 'const attendre = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\nasync function afficher() {\n  await attendre(250);\n  document.querySelector("#output").textContent = "Terminé après l’attente.";\n}\nafficher().catch(console.error);' }, expectedResult: 'Après un court délai, le message est mis à jour.' }, exercises: [
    { prompt: 'Déclare une fonction asynchrone nommée charger.', requiredSnippets: ['async function charger'], hint: 'Le mot async précède function.', explanation: 'async function charger() { ... } crée une fonction qui renvoie une Promise.' },
    { prompt: 'Attends la promesse resultat dans une fonction async.', requiredSnippets: ['await resultat'], hint: 'await précède la Promise.', explanation: 'const valeur = await resultat; attend la résolution dans la fonction async.' },
    { prompt: 'Rassemble deux promesses avec Promise.all.', requiredSnippets: ['Promise.all([', '])'], hint: 'La méthode reçoit un tableau de promesses.', explanation: 'await Promise.all([premiere, seconde]) attend les deux résultats.' }
  ], syntax: 'const resultat = await fetch(url);', lineByLine: 'await reprend la fonction après résolution et fournit la valeur accomplie. Si la promesse est rejetée, une exception est levée.', commonMistakes: 'await ne peut être utilisé que dans une fonction async ou dans un module selon l’environnement.', goodPractice: 'Utilise try/catch pour les rejets attendus et évite les callbacks async qui ignorent leurs propres erreurs.', related: ['Fetch API', 'Fonctions'], keywords: ['Promise', 'then', 'catch', 'finally', 'async', 'await', 'setTimeout', 'setInterval', 'event loop'] }] },
  { id: 'js-fetch', title: '15. Fetch et API HTTP', lessons: [{ id: 'js-fetch-api', title: 'Charger des données avec fetch', level: 'Avancé', introduction: 'fetch demande une ressource au réseau et renvoie une Promise de Response. Une réponse HTTP 404 ou 500 n’est pas automatiquement un rejet ; il faut vérifier response.ok.', syntax: 'const response = await fetch(url, { headers: { Accept: "application/json" } });\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst data = await response.json();', explanation: 'GET lit une ressource. POST transmet souvent un corps et un Content-Type. AbortController permet d’annuler une requête. CORS est une règle navigateur qui contrôle certaines requêtes inter-origines.', lineByLine: 'La réponse n’est pas encore les données : response.json() lit son corps et le parse de façon asynchrone. Le statut HTTP et les erreurs réseau doivent être traités distinctement.', commonMistakes: 'Oublier response.ok traite une réponse d’erreur comme une réussite. Une requête cross-origin peut échouer même si l’URL fonctionne dans un onglet.', goodPractice: 'Montre chargement, données vides et erreur ; valide la forme des données avant de les afficher.', callout: 'N’insère jamais directement une réponse réseau dans innerHTML.', example: { id: 'js-fetch', files: { html: '<button id="load">Charger une donnée locale</button><pre id="output"></pre>', css: 'button { padding: .6rem; } pre { white-space: pre-wrap; }', javascript: 'const button = document.querySelector("#load");\nbutton.addEventListener("click", async () => {\n  const output = document.querySelector("#output");\n  output.textContent = "Chargement…";\n  try {\n    const response = await fetch("data:application/json,%7B%22message%22%3A%22Bonjour%22%7D");\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    const data = await response.json();\n    output.textContent = data.message;\n  } catch (error) { output.textContent = error.message; }\n});' }, expectedResult: 'Le bouton charge une réponse JSON de démonstration et affiche son message, ou l’erreur.' }, exercises: [
    { prompt: 'Envoie une requête à url avec fetch et await.', requiredSnippets: ['await fetch(url)'], hint: 'fetch renvoie une Promise.', explanation: 'const response = await fetch(url); attend la réponse.' },
    { prompt: 'Traite explicitement une réponse HTTP non réussie.', requiredSnippets: ['response.ok', 'throw new Error'], hint: 'Teste la propriété ok avant de lire le corps.', explanation: 'if (!response.ok) throw new Error(...); traite les statuts HTTP non réussis.' },
    { prompt: 'Annule une requête avec AbortController en passant son signal.', requiredSnippets: ['new AbortController()', 'signal:', 'controller.signal'], hint: 'Le signal est une option de fetch.', explanation: 'const controller = new AbortController(); fetch(url, { signal: controller.signal }); puis controller.abort() annule.' }
  ], syntax: 'await response.json();', lineByLine: 'Le corps JSON est lu et parsé en objet JavaScript. Cette lecture retourne elle-même une Promise.', commonMistakes: 'Un corps vide ou un JSON mal formé fera rejeter json().', goodPractice: 'Valide les données et distingue erreurs réseau, statuts HTTP et erreurs de parsing.', related: ['Asynchronisme', 'Sécurité navigateur'], keywords: ['fetch', 'HTTP', 'GET', 'POST', 'headers', 'response.ok', 'JSON', 'AbortController', 'CORS'] }] },
  { id: 'js-browser-storage', title: '16. Stockage et API du navigateur', lessons: [{ id: 'js-web-apis', title: 'Utiliser les API natives du navigateur', level: 'Avancé', introduction: 'Le navigateur fournit des API qui ne font pas partie du langage ECMAScript : stockage local, URL, presse-papiers, géolocalisation, observers, workers, glisser-déposer et canvas. Chaque API a ses permissions et contraintes.', syntax: 'localStorage.setItem("theme", "clair");\nconst params = new URLSearchParams(location.search);\nconst observer = new IntersectionObserver(callback);', explanation: 'localStorage stocke des chaînes par origine et persiste après fermeture ; sessionStorage vit pour la session d’onglet. Clipboard et Geolocation demandent souvent un contexte sécurisé et un geste utilisateur.', lineByLine: 'IntersectionObserver surveille l’intersection sans calculer le scroll à chaque événement ; ResizeObserver observe les dimensions. Web Workers déplacent du calcul hors du thread UI mais ne manipulent pas directement le DOM.', commonMistakes: 'Le stockage local peut être indisponible ou rempli ; JSON.parse peut échouer. Une permission refusée doit être gérée. Un worker ne partage pas le DOM.', goodPractice: 'Encapsule les accès, valide les données, affiche un fallback et demande seulement les permissions nécessaires au moment où la personne comprend leur usage.', callout: 'Canvas dessine des pixels ; ajoute une alternative textuelle ou un contenu de remplacement compréhensible.', example: { id: 'js-web-apis', files: { html: '<button id="save">Mémoriser un prénom</button><p id="output"></p>', css: '', javascript: 'const button = document.querySelector("#save");\nconst output = document.querySelector("#output");\nbutton.addEventListener("click", () => {\n  try {\n    localStorage.setItem("prenom-exemple", "Awa");\n    output.textContent = `Bonjour ${localStorage.getItem("prenom-exemple")}`;\n  } catch { output.textContent = "Stockage indisponible"; }\n});' }, expectedResult: 'Le bouton enregistre une petite valeur et la relit en gérant une éventuelle indisponibilité.' }, exercises: [
    { prompt: 'Enregistre la valeur theme dans localStorage sous la clé couleur.', requiredSnippets: ['localStorage.setItem("couleur", theme)'], hint: 'setItem prend une clé et une valeur.', explanation: 'localStorage.setItem("couleur", theme) persiste la chaîne sous cette clé.' },
    { prompt: 'Lis le paramètre de recherche q avec URLSearchParams.', requiredSnippets: ['new URLSearchParams', 'params.get("q")'], hint: 'Crée d’abord URLSearchParams à partir de location.search.', explanation: 'const params = new URLSearchParams(location.search); params.get("q"); lit q.' },
    { prompt: 'Crée un IntersectionObserver qui appelle callback.', requiredSnippets: ['new IntersectionObserver(callback)'], hint: 'Le callback est passé au constructeur.', explanation: 'const observer = new IntersectionObserver(callback); crée l’observateur ; il faut ensuite observer un élément.' }
  ], syntax: 'sessionStorage.setItem("brouillon", texte);', lineByLine: 'La valeur est stockée comme chaîne. Les objets doivent être sérialisés avec JSON.stringify puis parsés avec JSON.parse.', commonMistakes: 'Ne stocke pas secrets ni informations sensibles dans ces stockages accessibles aux scripts de la page.', goodPractice: 'Prévois les erreurs d’accès et limite les données au strict nécessaire.', related: ['Sécurité', 'Asynchronisme'], keywords: ['localStorage', 'sessionStorage', 'Clipboard', 'History', 'Geolocation', 'IntersectionObserver', 'ResizeObserver', 'Web Workers', 'Drag and Drop', 'Canvas', 'Web Components'] }] },
  { id: 'js-modules-security', title: '17. Modules, sécurité et bonnes pratiques', lessons: [{ id: 'js-modules-xss', title: 'Organiser les modules et protéger les entrées', level: 'Avancé', introduction: 'Les modules ES séparent les responsabilités avec export et import. La sécurité côté navigateur commence par traiter les textes provenant d’un formulaire, d’un stockage ou d’une API comme non fiables.', syntax: '// format.js\nexport function formater(nom) { return `Bonjour ${nom}`; }\n// app.js\nimport { formater } from "./format.js";', explanation: 'type="module" active les imports dans le navigateur. textContent insère du texte. innerHTML analyse une chaîne comme balisage et peut permettre une injection XSS si du contenu non fiable y est placé.', lineByLine: 'Une CSP peut réduire certains risques mais ne rend pas le code sûr à elle seule. Les outils développeur permettent de poser des points d’arrêt et inspecter la pile d’appels.', commonMistakes: 'Ne concatène pas une donnée utilisateur dans une chaîne HTML. Ne masque pas une erreur avec un catch vide. Un import doit résoudre vers un chemin accessible.', goodPractice: 'Sépare les modules par responsabilité, garde des fonctions testables et utilise textContent ou createElement pour construire le DOM.', callout: 'La sandbox de l’éditeur protège le contexte privilégié de l’application, mais le code de l’apprenant reste du code exécutable dans une iframe isolée.', example: { id: 'js-security', files: { html: '<label for="name">Ton nom</label><input id="name"><button id="greet">Saluer</button><p id="output"></p>', css: '', javascript: 'const input = document.querySelector("#name");\ndocument.querySelector("#greet").addEventListener("click", () => {\n  document.querySelector("#output").textContent = `Bonjour ${input.value}`;\n});' }, expectedResult: 'Le texte saisi est présenté comme texte brut, sans interprétation HTML.' }, exercises: [
    { prompt: 'Exporte une fonction formater depuis un module ES.', requiredSnippets: ['export function formater'], hint: 'export précède la déclaration.', explanation: 'export function formater(...) { ... } rend la fonction importable.' },
    { prompt: 'Affiche une chaîne utilisateur comme texte brut dans output.', requiredSnippets: ['output.textContent'], hint: 'Utilise une propriété DOM qui ne parse pas HTML.', explanation: 'output.textContent = valeur; affiche la chaîne sans l’interpréter comme balisage.' },
    { prompt: 'Importe formater depuis ./format.js.', requiredSnippets: ['import', 'formater', 'from "./format.js"'], hint: 'Utilise un import nommé avec accolades.', explanation: 'import { formater } from "./format.js"; importe l’export nommé.' }
  ], syntax: 'import { formater } from "./format.js";', lineByLine: 'Les accolades désignent un export nommé. Le chemin relatif est résolu depuis le fichier courant.', commonMistakes: 'Les modules navigateur doivent être servis par un serveur et non toujours ouverts en file://.', goodPractice: 'Réduis les entrées dangereuses, vérifie les erreurs et adopte un formatage cohérent.', related: ['DOM', 'Fetch API'], keywords: ['import', 'export', 'XSS', 'innerHTML', 'textContent', 'debugging', 'performance', 'security'] }] },
  { id: 'js-reference', title: '18. Référence JavaScript', lessons: [{ id: 'js-reference-methods', title: 'Retrouver une méthode et son contexte', level: 'Avancé', introduction: 'La référence distingue les fonctionnalités ECMAScript des interfaces navigateur. Pour choisir une méthode, pars de la structure de données : chaîne, tableau, objet, date, promesse ou API Web.', syntax: 'texte.includes("web")\ntableau.filter(element => condition)\nObject.entries(objet)\nnew Date().toISOString()\nPromise.all(promesses)', explanation: 'La référence d’une API doit préciser ses paramètres, sa valeur de retour, ses mutations et les erreurs possibles. Certaines méthodes modifient la collection ; d’autres créent un résultat nouveau.', lineByLine: 'Chaînes : includes, slice, trim, replace. Tableaux : map, filter, find, reduce, some, every, sort. Objets : keys, values, entries. Promesses : then, catch, finally, all.', commonMistakes: 'Choisir une méthode par son nom sans vérifier si elle mute ou quelle valeur elle renvoie entraîne des bugs subtils.', goodPractice: 'Lis les paramètres et la valeur de retour, cherche un petit exemple reproductible et vérifie la compatibilité navigateur pour une API Web.', callout: 'La recherche de schoolweb indexe les titres, mots-clés et descriptions de ces notions.', example: { id: 'js-reference', files: { html: '<p id="output"></p>', css: '', javascript: 'const ventes = [1200, 900, 1600];\nconst total = ventes.reduce((sum, vente) => sum + vente, 0);\nconst moyen = total / ventes.length;\ndocument.querySelector("#output").textContent = new Intl.NumberFormat("fr-FR", { style: "currency", currency: "XOF" }).format(moyen);' }, expectedResult: 'Une moyenne est calculée avec reduce et formatée via Intl.' }, exercises: [
    { prompt: 'Calcule une somme à partir d’un tableau nombres avec reduce.', requiredSnippets: ['nombres.reduce(', '=>'], hint: 'reduce reçoit un accumulateur et une valeur courante.', explanation: 'nombres.reduce((total, valeur) => total + valeur, 0) agrège les éléments.' },
    { prompt: 'Transforme chaque élément avec map et produis un nouveau tableau.', requiredSnippets: ['.map(', '=>'], hint: 'map prend une fonction de transformation.', explanation: 'const nouveau = tableau.map(element => transformation); produit un tableau dérivé.' },
    { prompt: 'Attend plusieurs tâches asynchrones ensemble avec Promise.all.', requiredSnippets: ['Promise.all('], hint: 'Cette méthode agrège un itérable de promesses.', explanation: 'Promise.all(promesses) fournit une Promise qui se résout quand toutes réussissent.' }
  ], syntax: 'const resultat = tableau.map(transformer);', lineByLine: 'map appelle transformer pour chaque élément et collecte les valeurs retournées dans un tableau de même longueur.', commonMistakes: 'Si le callback ne retourne rien, le nouveau tableau contiendra undefined.', goodPractice: 'Choisis une méthode dont le nom exprime l’intention et garde un callback prévisible.', related: ['Tableaux', 'Asynchronisme'], keywords: ['reference', 'arrays', 'strings', 'objects', 'numbers', 'dates', 'promises', 'web APIs'] }] }
];

